widget.solution:
from math import gcd


def is_cyclic_units(n):
    units = [a for a in range(1, n) if gcd(a, n) == 1]
    for g in units:
        x, k = g, 1
        while x != 1:
            x = x * g % n
            k += 1
        if k == len(units):
            return True
    return False
